public final class AdvancedSystemsGameTest {
 static ServerPlayer player(GameTestHelper c){var cookie=net.minecraft.server.network.CommonListenerCookie.createInitial(new com.mojang.authlib.GameProfile(UUID.randomUUID(),"systems-test"),false);var p=new ServerPlayer(c.getLevel().getServer(),c.getLevel(),cookie.gameProfile(),cookie.clientInformation());var connection=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);c.getLevel().getServer().getPlayerList().placeNewPlayer(connection,p,cookie);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);while(!p.connection.hasClientLoaded())p.connection.tickClientLoadTimeout();var pos=c.absolutePos(new BlockPos(1,2,1));p.teleportTo(pos.getX(),pos.getY(),pos.getZ());return p;}
 static void grant(LivingEntity p,Art art,Metal metal){UUID id=UUID.randomUUID();p.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.grant(p.getAttachedOrCreate(ModRegistries.SPIRITWEB),new PowerGrant(id,art,metal,PowerGrant.Origin.ADMIN,id,1)));}
 static ItemStack mind(ServerPlayer p,FeruchemicalAttribute attr,long charge){var l=MetalmindLedger.get(p.level().getServer());var lease=new AssetLease(UUID.randomUUID(),0);var a=l.claim(l.create(attr,9000000,1,false).token(),lease);if(charge>0)a=l.change(a.token(),lease,p.getAttachedOrCreate(ModRegistries.SPIRITWEB).identity(),charge);a=l.release(a.token(),lease);var stack=new ItemStack(EconomyContent.item(attr.metal().id(),"ring"));stack.set(ModRegistries.METALMIND,MetalmindData.of(a));return stack;}
 static SpikeAsset spike(ServerPlayer p,int slot,Metal metal,StolenPower power,ConstructLedger.Purpose purpose){var a=SpikeLedger.get(p.level().getServer()).create(metal,power,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,p.level().getGameTime());if(purpose!=null)ConstructLedger.get(p.level().getServer()).prepare(a,purpose);var item=new ItemStack(EconomyContent.item(metal.id(),"spike"));item.set(ModRegistries.SPIKE,SpikeData.of(a));p.getInventory().setSelectedSlot(0);p.getInventory().setItem(0,item);HemalurgyRuntime.implant(p,slot,slot==11);return a;}
 @GameTest public void actualCompoundingRequiresIntentAbilitiesContactAndConsumesSourceOnce(GameTestHelper c){var p=player(c);grant(p,Art.ALLOMANCY,Metal.GOLD);grant(p,Art.FERUCHEMY,Metal.GOLD);p.getInventory().setItem(0,mind(p,FeruchemicalAttribute.HEALTH,0));ContactService.equip(p,0,0);var source=mind(p,FeruchemicalAttribute.HEALTH,1000);var copy=source.copy();p.getInventory().setItem(0,source);c.assertFalse(AdvancedSystems.act(p,new SystemsIntent(1,0,0,false)),"No implicit consumption");c.assertTrue(!p.getMainHandItem().isEmpty(),"Intent refusal preserves source");c.assertTrue(AdvancedSystems.act(p,new SystemsIntent(1,0,0,true)),"Real charged material compounds");var token=ContactService.equipment(p).item(0).get(ModRegistries.METALMIND).token();c.assertTrue(p.getMainHandItem().isEmpty()&&MetalmindLedger.get(c.getLevel().getServer()).resolve(token).charge()==10000,"Exact amplified charge, physical source consumed");p.getInventory().setItem(0,copy);c.assertFalse(AdvancedSystems.act(p,new SystemsIntent(1,0,0,true)),"Copied consumed token cannot burn twice");c.assertTrue(MetalmindLedger.get(c.getLevel().getServer()).resolve(token).charge()==10000,"No duplicate output");c.succeed();}
 @GameTest public void protectionAdapterDeniesMentalContactAndCompoundingWithoutStateChanges(GameTestHelper c){var p=player(c);var target=c.spawn(EntityType.VILLAGER,new BlockPos(1,2,2));target.addTag("systems_protected");p.teleportTo(target.getX()+1,target.getY(),target.getZ());ArtsProtection.EVENT.register((actor,victim,action)->!victim.entityTags().contains("systems_protected"));c.assertFalse(EmotionService.influence(p,target,EmotionProfile.Emotion.FEAR,.01),"Protection adapter blocks emotions");p.addTag("systems_protected");grant(p,Art.ALLOMANCY,Metal.IRON);grant(p,Art.FERUCHEMY,Metal.IRON);var source=mind(p,FeruchemicalAttribute.WEIGHT,1000);p.getInventory().setItem(0,source);c.assertFalse(AdvancedSystems.act(p,new SystemsIntent(1,0,0,true)),"Self action protection checked before any mutation");c.assertTrue(!p.getMainHandItem().isEmpty()&&MetalmindLedger.get(c.getLevel().getServer()).resolve(source.get(ModRegistries.METALMIND).token()).charge()==1000,"Denied source retained exactly");c.succeed();}
 @GameTest public void kolossNeedsFourPreparedStaplesAndLosesCapabilitiesOnRemoval(GameTestHelper c){var p=player(c);for(int slot:new int[]{0,1,4,5})spike(p,slot,Metal.IRON,new StolenPower(StolenPower.Kind.STRENGTH,Metal.IRON),ConstructLedger.Purpose.KOLOSS_STAPLE);ConstructRuntime.transform(p,ConstructState.Kind.KOLOSS);c.assertTrue(p.getAttribute(Attributes.SCALE).getValue()>1&&p.getMaxHealth()>20,"Distinct grown body and endurance");p.getInventory().clearContent();HemalurgyRuntime.remove(p,0);ConstructRuntime.tick(p,1);c.assertTrue(!ConstructRuntime.inspect(p).koloss()&&!p.getAttribute(Attributes.ATTACK_DAMAGE).hasModifier(MetallicArts.id("construct_force")),"Removing required anatomy stops construct force");c.succeed();}
 @GameTest public void arbitrarySpikesCannotActivateConstructTemplates(GameTestHelper c){var p=player(c);for(int slot:new int[]{0,1,4,5})spike(p,slot,Metal.IRON,new StolenPower(StolenPower.Kind.STRENGTH,Metal.IRON),null);boolean denied=false;try{ConstructRuntime.transform(p,ConstructState.Kind.KOLOSS);}catch(IllegalArgumentException e){denied=true;}c.assertTrue(denied&&p.getAttachedOrCreate(ModRegistries.CONSTRUCT).kind()==ConstructState.Kind.HUMAN,"No generic stat shortcut without preparation");c.succeed();}
 @GameTest public void kandraRequiresMistwraithAndLinkedBlessingThenConsumesShapeMaterials(GameTestHelper c){var p=player(c);ConstructRuntime.lineage(p,ConstructState.Lineage.MISTWRAITH);var ledger=SpikeLedger.get(c.getLevel().getServer());var a=ledger.create(Metal.IRON,new StolenPower(StolenPower.Kind.STRENGTH,Metal.IRON),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,0);var b=ledger.create(Metal.IRON,new StolenPower(StolenPower.Kind.STRENGTH,Metal.IRON),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,0);ConstructLedger.get(c.getLevel().getServer()).bless(a,b);for(int i=0;i<2;i++){var stack=new ItemStack(EconomyContent.item("iron","spike"));stack.set(ModRegistries.SPIKE,SpikeData.of(i==0?a:b));p.getInventory().setItem(0,stack);HemalurgyRuntime.implant(p,i,false);}ConstructRuntime.transform(p,ConstructState.Kind.KANDRA);p.getInventory().setItem(0,new ItemStack(Items.BONE,8));p.getInventory().setItem(1,new ItemStack(Items.LEATHER,2));ConstructRuntime.shape(p,ConstructState.Shape.WOLF);c.assertTrue(p.getInventory().getItem(0).isEmpty()&&p.getInventory().getItem(1).isEmpty()&&p.getAttribute(Attributes.SCALE).getValue()<1,"Real shape materials and collision body change");p.getInventory().clearContent();HemalurgyRuntime.remove(p,0);HemalurgyRuntime.remove(p,1);ConstructRuntime.tick(p,2);c.assertFalse(ConstructRuntime.canUsePowers(p),"Loss of both Blessing members collapses cognition");c.assertTrue(p.getAttachedOrCreate(ModRegistries.CONSTRUCT).degradedTicks()>0,"Loss state persists without deleting memory");c.succeed();}
 @GameTest public void inquisitorEyesGoldAndLinchpinHaveRealDependencies(GameTestHelper c){var p=player(c);for(int slot=0;slot<12;slot++){if(slot==10)continue;Metal metal=slot==2||slot==3?Metal.STEEL:slot==6?Metal.GOLD:slot==7||slot==8||slot==9?Metal.PEWTER:Metal.STEEL;var power=slot==6?new StolenPower(StolenPower.Kind.FERUCHEMY,Metal.GOLD):slot==7||slot==8||slot==9?new StolenPower(StolenPower.Kind.FERUCHEMY,Metal.IRON):new StolenPower(StolenPower.Kind.ALLOMANCY,Metal.STEEL);var purpose=slot==2||slot==3?ConstructLedger.Purpose.INQUISITOR_EYE:slot==11?ConstructLedger.Purpose.INQUISITOR_PIN:null;spike(p,slot,metal,power,purpose);}HemalurgyRuntime.tick(p,100);ConstructRuntime.transform(p,ConstructState.Kind.INQUISITOR);c.assertTrue(p.getMaxHealth()>20&&ConstructRuntime.inspect(p).inquisitor(),"Eleven real canonical spikes form the supported template");p.getInventory().clearContent();HemalurgyRuntime.remove(p,11);c.assertFalse(p.isAlive(),"Critical body dependency is lethal exactly on removal");c.succeed();}
 @GameTest public void exceptionalExtractionIsOptInAndProtectedFailuresRollBack(GameTestHelper c){var p=player(c);var donor=c.spawn(EntityType.VILLAGER,new BlockPos(2,2,2));p.teleportTo(donor.getX()+1,donor.getY(),donor.getZ());grant(donor,Art.ALLOMANCY,Metal.STEEL);p.getInventory().setItem(0,new ItemStack(EconomyContent.item("steel","spike")));var power=new StolenPower(StolenPower.Kind.ALLOMANCY,Metal.STEEL);boolean denied=false;try{HemalurgyRuntime.extract(p,donor,power,true);}catch(IllegalArgumentException e){denied=true;}c.assertTrue(denied&&donor.isAlive(),"Closed by default");var original=AdvancedConfig.get();try{AdvancedConfig.install(AdvancedConfig.parse("{\"constructs\":{\"exceptionalExtraction\":true}}"));donor.setInvulnerable(true);var before=donor.getAttachedOrCreate(ModRegistries.SPIRITWEB);denied=false;try{HemalurgyRuntime.extract(p,donor,power,true);}catch(IllegalArgumentException e){denied=true;}c.assertTrue(denied&&before.equals(donor.getAttachedOrCreate(ModRegistries.SPIRITWEB))&&!p.getMainHandItem().has(ModRegistries.SPIKE),"Cancelled injury restores source and item");donor.setInvulnerable(false);HemalurgyRuntime.extract(p,donor,power,true);c.assertTrue(donor.isAlive()&&donor.getHealth()<20&&donor.getAttachedOrCreate(ModRegistries.SPIRITUAL_WOUNDS)==1&&donor.getAttachedOrCreate(ModRegistries.SPIRITWEB).grants().isEmpty(),"Nonlethal extraction still surrenders power and leaves permanent spiritual injury");var spike=SpikeLedger.get(c.getLevel().getServer()).resolve(p.getMainHandItem().get(ModRegistries.SPIKE).token());c.assertTrue(spike.extractedStrength()==.25,"Explicit lower-retention rule");}finally{AdvancedConfig.install(original);}c.succeed();}
 @GameTest public void severeInjuryHasConsequencesAndGoldCurePaysForOneLevel(GameTestHelper c){var p=player(c);grant(p,Art.FERUCHEMY,Metal.GOLD);p.getInventory().setItem(0,mind(p,FeruchemicalAttribute.HEALTH,100000));ContactService.equip(p,0,0);p.setAttached(ModRegistries.TRAUMA,new TraumaState(1,1,0));p.setHealth(20);c.assertTrue(FeruchemyRuntime.act(p,new ContactIntent(2,0,0,2,3),100),"Arm healing at full health");FeruchemyRuntime.tick(p,100);var a=MetalmindLedger.get(c.getLevel().getServer()).resolve(ContactService.equipment(p).item(0).get(ModRegistries.METALMIND).token());c.assertTrue(p.getAttachedOrCreate(ModRegistries.TRAUMA).total()==1&&a.charge()==50000,"One exact paid trauma recovery");c.succeed();}
 @GameTest public void repairCanRefreshOnlyExistingMatchingCanonicalOwnerAndNeverCreateCharge(GameTestHelper c){var p=player(c);p.getInventory().setItem(0,mind(p,FeruchemicalAttribute.WEIGHT,250));ContactService.equip(p,0,0);var old=ContactService.equipment(p).item(0).get(ModRegistries.METALMIND);var l=MetalmindLedger.get(c.getLevel().getServer());var lease=new AssetLease(p.getUUID(),0);var free=l.release(old.token(),lease);var current=l.claim(free.token(),lease);c.assertTrue(SystemsCommands.audit(p,true)==1,"Operator repair updates one stale owned reference");c.assertTrue(ContactService.equipment(p).item(0).get(ModRegistries.METALMIND).token().equals(current.token())&&l.resolve(current.token()).charge()==250,"Repair imports no preview charge");c.succeed();}
 @GameTest public void npcBurnsPayActualFuelAndNativeCombatAttributes(GameTestHelper c){var mob=c.spawn(EntityType.ZOMBIE,new BlockPos(2,2,2));grant(mob,Art.ALLOMANCY,Metal.PEWTER);mob.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.credit(mob.getAttachedOrCreate(ModRegistries.SPIRITWEB),Metal.PEWTER,10000));c.assertTrue(NpcArts.request(mob,Metal.PEWTER,BurnMode.BURN),"Actual owned NPC power activates");NpcArts.prepare(c.getLevel().getServer());NpcArts.apply();c.assertTrue(mob.getAttribute(Attributes.ATTACK_DAMAGE).hasModifier(MetallicArts.id("npc_pewter"))&&ReserveLedger.ordinary(mob.getAttachedOrCreate(ModRegistries.SPIRITWEB),Metal.PEWTER)<10000,"Paid effect really changes NPC combat");NpcArts.leech(mob);NpcArts.apply();c.assertTrue(mob.getAttachedOrCreate(ModRegistries.SPIRITWEB).reserves().isEmpty()&&!mob.getAttribute(Attributes.ATTACK_DAMAGE).hasModifier(MetallicArts.id("npc_pewter")),"Contact depletion stops native effect");NpcArts.clear();c.succeed();}
 @GameTest public void stoppedShortBurnRemainsDetectableAndCopperDoesNotRetroactivelyLeak(GameTestHelper c){var target=player(c);var seeker=player(c);seeker.teleportTo(target.getX()+2,target.getY(),target.getZ());grant(target,Art.ALLOMANCY,Metal.STEEL);target.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.credit(target.getAttachedOrCreate(ModRegistries.SPIRITWEB),Metal.STEEL,1000));AllomancyRuntime.request(target,0,1,100);AllomancyRuntime.prepare(target,100);PulseHistory.record(c.getLevel().getServer());AllomancyRuntime.stopMetal(target,Metal.STEEL);c.assertTrue(PulseHistory.detectable(seeker,1).stream().anyMatch(pulse->pulse.owner()==target&&pulse.metals().contains(Metal.STEEL)),"Real paid short pulse survives sampling gap");AllomancyRuntime.stop(target);c.succeed();}
 @GameTest public void memoryRenameAndSearchPreserveIdentityAndCannotRenameStoredKnowledge(GameTestHelper c){var p=player(c);var memory=new MemoryEntry(UUID.randomUUID(),"discovery","Old label","minecraft:overworld",1,80,2,1);p.setAttached(ModRegistries.JOURNAL,new ArtsJournal(List.of(memory),List.of(memory),List.of("observed")));grant(p,Art.FERUCHEMY,Metal.COPPER);p.getInventory().setItem(0,mind(p,FeruchemicalAttribute.MEMORY,0));ContactService.equip(p,0,0);c.assertTrue(AdvancedFeruchemy.memory(p,new MemoryAction(3,0,0,memory.id(),"My refuge")),"Owner annotates accessible record");var entry=p.getAttachedOrCreate(ModRegistries.JOURNAL).memories().getFirst();c.assertTrue(entry.id().equals(memory.id())&&entry.time()==memory.time()&&entry.x()==memory.x()&&ArtsJournal.matches(entry,"REFUGE"),"Annotation does not forge event provenance");AdvancedFeruchemy.memory(p,new MemoryAction(1,0,0,memory.id()));c.assertFalse(AdvancedFeruchemy.memory(p,new MemoryAction(3,0,0,memory.id(),"Forbidden")),"Stored knowledge is unavailable to rename");c.succeed();}
}
